"""Shared test configuration: headless plotting and small reusable fixtures."""

import matplotlib

matplotlib.use("Agg")

import numpy as np
import pytest


@pytest.fixture
def rotation_map():
    """A stable 2-D linear map ``A = 0.95 * R(theta)`` and a trajectory generated by it."""
    theta = 0.3
    A = 0.95 * np.array([[np.cos(theta), -np.sin(theta)], [np.sin(theta), np.cos(theta)]])
    x = [np.array([1.0, 0.5])]
    for _ in range(60):
        x.append(A @ x[-1])
    return A, np.array(x), theta
